import{_ as s,o as a,c as t,a5 as i}from"./chunks/framework.DSg0KOwT.js";const g=JSON.parse('{"title":"Behind an SSH bastion","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/alternative-log-retrieval/ssh-bastion.md","filePath":"user-guide/alternative-log-retrieval/ssh-bastion.md"}'),o={name:"user-guide/alternative-log-retrieval/ssh-bastion.md"};function r(h,e,n,l,p,d){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="behind-an-ssh-bastion" tabindex="-1">Behind an SSH bastion <a class="header-anchor" href="#behind-an-ssh-bastion" aria-label="Permalink to &quot;Behind an SSH bastion&quot;">​</a></h1><p>How to fetch a History Server log when the server is only reachable through an SSH bastion.</p><p>The most common hard case is a Spark History Server (SHS) reachable only through an SSH bastion or jump host (the recipe below is the same regardless of what&#39;s issuing the SSH session), with the event logs themselves living on Kerberized HDFS and no direct HTTP path from your machine to SHS.</p><h2 id="why-shs-base-url-won-t-work-here" tabindex="-1">Why <code>--shs-base-url</code> won&#39;t work here <a class="header-anchor" href="#why-shs-base-url-won-t-work-here" aria-label="Permalink to &quot;Why `--shs-base-url` won&#39;t work here&quot;">​</a></h2><p>The CLI&#39;s <code>--shs-base-url</code>/<code>--app-id</code> flags and the MCP tools&#39; <code>{ shsBaseUrl, appId }</code> source both make a direct HTTP request from wherever SparkForensics runs to the History Server&#39;s REST API. There&#39;s no <code>--via-ssh</code> flag. If the bastion can reach the History Server&#39;s HTTP port, forward it (<code>ssh -L 18080:&lt;shs-host&gt;:18080 &lt;bastion&gt;</code>) and use <code>--shs-base-url http://127.0.0.1:18080</code>. SparkForensics sends no credentials, so a History Server that requires Kerberos/SPNEGO sign-in can&#39;t be fetched this way: use the recipe below.</p><p>Running in Airflow? The <a href="https://github.com/shuffle-works/sparkforensics-operator" target="_blank" rel="noreferrer">sparkforensics-operator</a> can fetch the log from a History Server behind an SSH tunnel, or run the analysis on an SSH host that already sees the logs.</p><h2 id="the-recipe" tabindex="-1">The recipe <a class="header-anchor" href="#the-recipe" aria-label="Permalink to &quot;The recipe&quot;">​</a></h2><ol><li><p>SSH into the edge node (through the bastion, or whatever gets you there).</p></li><li><p>Pull the event log off HDFS onto local disk on the edge node:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hdfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dfs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/spark-events/application_XXXX_XXXX</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/application_XXXX_XXXX</span></span></code></pre></div></li><li><p>Copy that file back to your own machine through the same bastion, e.g. with <code>scp</code> or <code>sftp</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> edge-node:/tmp/application_XXXX_XXXX</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./application_XXXX_XXXX</span></span></code></pre></div></li><li><p>Load the local copy as described in <a href="./../alternative-log-retrieval.html#loading-the-file">Loading the file</a>.</p></li></ol>',8)])])}const b=s(o,[["render",r]]);export{g as __pageData,b as default};
